import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    opp_def = sum(1 for a in op if a == 'D')
    my_def = sum(1 for a in my if a == 'D')

    # If opponent almost always defects, just defect.
    if n >= 5 and opp_def >= n - 1:
        return 'D'

    # Detect alternator: opponent alternates. Exploit by defecting when we predict C.
    if n >= 6:
        alt = 0
        for i in range(2, n):
            if op[i] != op[i - 2]:
                alt += 1
        if alt >= n - 3:
            # Predict next as opposite of last; defect if predicted C, else C
            return 'D' if op[-1] == 'C' else 'C'

    # Detect sustained cooperator / highly cooperative opponent.
    coop_rate = (n - opp_def) / n
    if coop_rate > 0.85 and n >= 12:
        # Near endgame exploit aggressively, but keep some cooperation early.
        if n >= 92:
            return 'D'
        if n >= 85:
            return 'D' if rng.random() < 0.7 else 'C'
        # Occasionally defect to skim DC without destabilizing too much.
        if n >= 25 and rng.random() < 0.12:
            return 'D'
        return 'C'

    # Endgame exploitation for moderately cooperative opponents.
    if n >= 92:
        if coop_rate > 0.5:
            return 'D'
        if coop_rate < 0.25:
            return 'D'
        return 'C'

    # If opponent just defected:
    last_op = op[-1]
    last_my = my[-1]
    if last_op == 'D':
        # If we've been cooperating steadily and this is an isolated defection,
        # punish once then return to cooperation.
        recent_op = op[-6:]
        recent_def = sum(1 for a in recent_op if a == 'D')
        if recent_def <= 1 and my_def <= 1 and n >= 4:
            # Retaliate once, but if we already retaliated last round, forgive.
            if last_my == 'D':
                return 'C'
            return 'D'
        if recent_def >= 3:
            return 'D'
        if last_my == 'D':
            # In a defection exchange; try to break out if opponent cooperates often.
            if coop_rate > 0.6 and rng.random() < 0.7:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last round.
    # If we defected last round and opponent still cooperated, they don't punish.
    # Exploit slightly more against such forgiving opponents.
    if last_my == 'D' and n >= 3:
        # Count how often opponent cooperated after our D.
        forgiving = 0
        chances = 0
        for i in range(1, n):
            if my[i - 1] == 'D':
                chances += 1
                if op[i] == 'C':
                    forgiving += 1
        if chances >= 2 and forgiving >= chances:
            # Opponent is a pushover; exploit harder.
            if n >= 30 and rng.random() < 0.5:
                return 'D'
            return 'C'

    # If opponent is somewhat defective, use probabilistic retaliation.
    if opp_def * 3 >= n:
        # Moderate defector: TFT-ish with forgiveness.
        if op[-1] == 'D':
            return 'D'
        if rng.random() < 0.9:
            return 'C'
        return 'D'

    # General cooperative stance.
    return 'C'
